/**
 * Displays the given angle in the text field of a servo. The value shown is exactly the
 * progress of the corresponding SeekArc, so that the displayed value never differs from the
 * value the arc was set to.
 */
private void setDegreeText(EditText degreeText, int degrees) {
    degreeText.setText(String.valueOf(degrees));
    degreeText.setCursorVisible(false);
}

private void processDegreeInput(EditText degreeText, SeekArc seekArc) {
    String degreeStr = degreeText.getText().toString().trim();

    int degree;
    if (degreeStr.isEmpty()) {
        // Nothing was entered, so keep the angle the servo is currently set to.
        degree = seekArc.getProgress();
    } else {
        try {
            degree = Integer.parseInt(degreeStr);
        } catch (NumberFormatException e) {
            degree = -1;
        }
    }

    if (degree > MAX_DEGREE || degree < 0) {
        seekArc.setProgress(0);
        setDegreeText(degreeText, 0);
        toastInvalidValueMessage();
    } else {
        // The SeekArc reports the new progress back through its change listener, which
        // updates the text field with the very same value.
        seekArc.setProgress(degree);
        setDegreeText(degreeText, degree);
    }
}

