''')
s=s.replace('new InputMinMaxFilter(0, MAX_DEGREE)','new InputMinMaxFilter(0, 360)')
for n in '1234':
    s=s.replace('                setDegreeText(degreeText%s, i);'%n,'''                if (editEnter) {
                    degreeText%s.setText(String.valueOf(degree));
                    editEnter = false;
                } else {
                    degreeText%s.setText(String.valueOf((int) (i * 3.6)));
                }
                degreeText%s.setCursorVisible(false);'''%(n,n,n))
old=s[s.index('    /**\n     * Displays the given angle'):s.index('    private void saveTimeline()')]
s=s.replace(old,'''    private void processDegreeInput(EditText degreeText, SeekArc seekArc) {
        int previousDegree = degree;
        String degreeStr = degreeText.getText().toString().trim();

        if (degreeStr.isEmpty()) {
            degree = (degree == 0) ? (int) (seekArc.getProgress() * 3.6) : previousDegree;
        } else {
            try {
                degree = Integer.parseInt(degreeStr);
            } catch (NumberFormatException e) {
                degreeText.setText(getResources().getString(R.string.zero));
                seekArc.setProgress(0);
                toastInvalidValueMessage();
                return;
            }
        }

        if (degree > 360 || degree < 0) {
            degreeText.setText(getResources().getString(R.string.zero));
            seekArc.setProgress(0);
            toastInvalidValueMessage();
        } else {
            seekArc.setProgress((int) (degree / 3.6));
            editEnter = true;
        }
    }


''')
open(p,'w').write(s)
